def _quota_intervals(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        def feasible(selected):
            ids = {job["id"] for job in selected}
            if not mandatory.issubset(ids):
                return False
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            for group, (low, high) in quotas.items():
                count = counts.get(group, 0)
                if not low <= count <= high:
                    return False
            active = []
            for job in sorted(selected, key=lambda j: (j["start"], j["end"])):
                active = [end for end in active if end > job["start"]]
                if len(active) >= capacity:
                    return False
                active.append(job["end"])
            return True

        # Enumerating subsets is small (at most 14 jobs) and handles negative values
        # and all quota/mandatory interactions without greedy assumptions.
        from itertools import combinations
        for subset in combinations(options, k):
            if not feasible(subset):
                continue
            value = sum(job["value"] for job in subset)
            ids = tuple(sorted(job["id"] for job in subset))
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and ids < best_ids) or
                      (tie == "largest" and ids > best_ids)))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        # Each package can be absent, or installed at one of its available,
        # unblocked versions. Pins constrain installation but do not cause it.
        choices = []
        for name in names:
            versions = sorted({row["version"] for row in packages[name]
                               if row["version"] not in blocked.get(name, [])
                               and (name not in pins or row["version"] == pins[name])})
            choices.append([None] + versions)

        best_vector = None
        best_versions = None
        for values in product(*choices):
            selected = {name: version for name, version in zip(names, values)
                        if version is not None}
            if any(name not in selected or
                   not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            edges = {name: [] for name in selected}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name]
                           if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = selected.get(target)
                    if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            # All installed packages must belong to the active root closure.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(selected):
                continue

            # Reject cycles, including self-loops.
            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                state[name] = 2
                return True
            if not all(visit(name) for name in selected):
                continue

            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = selected
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_remaining in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask, next_remaining))
        return {"arrival": None}
    return solve


